(()=>{
const API='https://tablegame.jujuli.com.cn/api';let user=null,room=null,timer=0;
const css=`<style>#onlineMode{opacity:1!important;cursor:pointer!important}.mq-auth{font:14px Microsoft YaHei,system-ui;position:fixed;inset:0;background:#0006;z-index:9999;display:grid;place-items:center}.mq-card{width:min(390px,calc(100vw - 32px));background:#fffaf0;border-radius:24px;padding:24px;box-shadow:0 24px 80px #0003}.mq-card h2{margin:0 0 8px}.mq-card p{color:#756d61}.mq-card input{box-sizing:border-box;width:100%;padding:14px;margin:6px 0;border:1px solid #ddd3c3;border-radius:12px;font:inherit}.mq-card button{width:100%;padding:14px;margin-top:8px;border:0;border-radius:12px;font:inherit;font-weight:700}.mq-card .main{background:#1d1d1b;color:white}.mq-card .sub{background:#f1eadf}.mq-card .err{color:#a33;min-height:20px}.mq-user{border:0;background:transparent;font:inherit;padding:10px;cursor:pointer}</style>`;document.head.insertAdjacentHTML('beforeend',css);
const api=async(path,opt={})=>{const r=await fetch(API+path,{credentials:'include',headers:{'Content-Type':'application/json'},...opt});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||'网络请求失败');return d};
const modal=html=>{const x=document.createElement('div');x.className='mq-auth';x.innerHTML=`<div class="mq-card">${html}</div>`;document.body.append(x);x.addEventListener('click',e=>{if(e.target===x)x.remove()});return x};
async function loadUser(){try{user=(await api('/me')).user}catch{};renderUser()}
function renderUser(){let old=document.querySelector('.mq-user');old?.remove();const host=document.querySelector('.header-right');if(!host)return;const b=document.createElement('button');b.className='mq-user';b.textContent=user?user.username:'登录';b.onclick=()=>user?account():login();host.prepend(b)}
function login(after){const x=modal(`<h2>登录妙棋手</h2><p>与桌游大厅共用一个账号</p><input class="u" placeholder="用户名或邮箱"><input class="p" type="password" placeholder="密码（至少10位）"><div class="err"></div><button class="main">登录</button><button class="sub">注册新账号</button>`);const [go,reg]=x.querySelectorAll('button');const submit=async(kind)=>{try{const d=await api('/'+kind,{method:'POST',body:JSON.stringify({username:x.querySelector('.u').value,password:x.querySelector('.p').value})});user=d.user;x.remove();renderUser();after?.()}catch(e){x.querySelector('.err').textContent=e.message}};go.onclick=()=>submit('login');reg.onclick=()=>submit('register')}
function account(){const x=modal(`<h2>${user.username}</h2><p>已登录聚聚里桌游账号，在妙棋手和桌游大厅中通用。</p><button class="sub">退出登录</button>`);x.querySelector('button').onclick=async()=>{await api('/logout',{method:'POST',body:'{}'});user=null;x.remove();renderUser()}}
function online(){if(!user)return login(online);const x=modal(`<h2>联机对战</h2><p>创建棋局，或输入好友发来的 8 位房间码。</p><button class="main create">创建房间</button><input class="code" maxlength="8" placeholder="输入房间码"><button class="sub join">加入房间</button><div class="err"></div>`);x.querySelector('.create').onclick=async()=>{try{room=await api('/chess/rooms',{method:'POST',body:'{}'});x.remove();showRoom()}catch(e){x.querySelector('.err').textContent=e.message}};x.querySelector('.join').onclick=async()=>{try{const code=x.querySelector('.code').value.trim().toUpperCase();room=await api('/chess/rooms/'+code,{method:'POST',body:JSON.stringify({type:'join'})});x.remove();showRoom()}catch(e){x.querySelector('.err').textContent=e.message}}}
function showRoom(){const x=modal(`<h2>房间 ${room.code}</h2><p class="state"></p><button class="main copy">复制房间码</button><button class="sub enter">进入棋局</button><div class="err"></div>`);const state=x.querySelector('.state');const refresh=async()=>{try{room=await api('/chess/rooms/'+room.code);state.textContent=room.players.length<2?'等待好友加入…':'对手已加入，可以开始对局';x.querySelector('.enter').disabled=room.players.length<2}catch(e){state.textContent=e.message}};x.querySelector('.copy').onclick=()=>navigator.clipboard?.writeText(room.code);x.querySelector('.enter').onclick=()=>{x.remove();enterGame()};refresh();timer=setInterval(refresh,1200);x.addEventListener('remove',()=>clearInterval(timer))}
function enterGame(){clearInterval(timer);try{draftMode='online';mode='online';reset();navigate('game')}catch{};toast?.('联机房间 '+room.code+' · '+(room.side==='r'?'你执红':'你执黑'));sync();timer=setInterval(sync,900)}
async function sync(){if(!room)return;try{room=await api('/chess/rooms/'+room.code);if(typeof board!=='undefined'&&room.board){board=room.board;turn=room.turn;legal=XQ.moves(board,turn);ended=room.status==='ended';draw();}}catch{}}
const onlineBtn=document.getElementById('onlineMode');if(onlineBtn){onlineBtn.disabled=false;onlineBtn.removeAttribute('title');onlineBtn.setAttribute('aria-label','联机对战');const s=onlineBtn.querySelector('small');if(s)s.textContent='好友对战';onlineBtn.onclick=online}
loadUser();
})();